-- Queer Atlas: Houston, Portland, Rehoboth Beach, Phoenix and Honolulu hotels
-- Research and address check: 2026-08-27.
-- Adds 21 hotels: 4 each in Houston, Portland, Rehoboth Beach and Phoenix;
-- 5 in Honolulu, where The Surfjack Hotel & Swim Club already exists (6 total).
-- Inclusion claims are tied to official Pride, destination, hotel or specialist
-- LGBTQ+ sources. Coordinates are exact-address Mapbox results (relevance 1.0).
-- Safe to rerun. Canonical names and known aliases are checked per city.

begin;

alter table if exists public.places
  add column if not exists venue_intel jsonb not null default '{}'::jsonb;

with raw_hotels as (
  select * from jsonb_to_recordset($qa_hotels$
[
 {"name":"Hotel Saint Augustine","aliases":"Hotel Saint Augustine","city":"houston","description":"A small luxury hotel in Montrose whose 2026 Pride programme turned its listening-room series into weekly drag performances. Its location is close to Houston's historic queer district without presenting the property as queer-exclusive.","vibe":"intimate Montrose design hotel with culture-led Pride programming","tags":"luxury,cultural,cozy","hours":"Reception and overnight guest service operate daily; restaurant, pool and Listening Room programming use separate schedules.","link":"https://www.hotelsaintaugustine.com/","location":"4110 Loretto Drive, Houston, TX 77006, United States","lat":29.735738,"lng":-95.398226,"arrival":"The 71-room scale keeps ordinary arrival calm; Pride performances and restaurant reservations can concentrate valet and lobby traffic.","best":"Best for a design-focused Montrose stay and for guests who want verified Pride culture without a large convention-hotel atmosphere.","crowd":"Couples, architecture and food travellers, local restaurant guests and LGBTQ+ visitors mix in a polished boutique setting.","dress":"Relaxed luxury and smart-casual clothing fit the public rooms; pool and ticketed programmes set their own practical rules.","inclusion":"Visit Houston documents the hotel's June 2026 drag series, providing a current community signal rather than a generic rainbow claim.","basis":"Current official destination Pride programme plus first-party hotel operation.","class":"Luxury boutique hotel","coords":"Mapbox exact-address result for 4110 Loretto Drive; relevance 1.0.","sources":["https://www.visithoustontexas.com/lgbtq/post/pride-month-in-houston/","https://www.hotelsaintaugustine.com/"]},
 {"name":"La Colombe d'Or Hotel","aliases":"La Colombe d'Or Hotel|La Colombe d'Or","city":"houston","description":"A historic Montrose mansion joined to a modern residential tower, with art, restaurant, garden and pool. Houston's official LGBTQ neighbourhood guide recommends it as a stay inside the city's longstanding gayborhood.","vibe":"art-filled Montrose retreat pairing mansion history with modern suites","tags":"luxury,cultural,relax","hours":"Hotel reception operates daily; restaurant, bar, gallery and pool access follow current guest and reservation schedules.","link":"https://www.lacolombedor.com/","location":"3410 Montrose Boulevard, Houston, TX 77006, United States","lat":29.741635,"lng":-95.391690,"arrival":"A small mansion entrance and restaurant bookings shape arrival more than queues; confirm which building contains the reserved room.","best":"Best for art, quieter evenings and immediate Montrose context, with nightlife reached by a short walk or ride.","crowd":"Queer couples, art travellers, local diners, wedding guests and luxury visitors share a residential-feeling property.","dress":"Daytime is polished casual; smart-casual works for dinner and cocktails without implying a formal hotel-wide code.","inclusion":"The city's official LGBTQ guide places the property in its Montrose stay recommendations; it remains a mixed luxury hotel.","basis":"Official Houston LGBTQ neighbourhood recommendation plus first-party hotel information.","class":"Historic luxury boutique hotel","coords":"Mapbox exact-address result for 3410 Montrose Boulevard; relevance 1.0.","sources":["https://lgbtq.visithoustontexas.com/plan-your-vacation/neighborhoods/montrose/","https://www.lacolombedor.com/"]},
 {"name":"Hotel ZaZa Museum District","aliases":"Hotel ZaZa Museum District|Hotel ZaZa Houston Museum District|Hotel ZaZa Houston","city":"houston","description":"A theatrical boutique hotel beside Houston's museums and Hermann Park, with concept suites, spa, pool and restaurant. It appears repeatedly in Houston's official LGBTQ hotel and Montrose coverage.","vibe":"maximalist museum-district hotel with playful suites and poolside polish","tags":"luxury,cultural,social","hours":"Reception is continuous; spa, pool, restaurant and shuttle services follow current hotel schedules.","link":"https://www.hotelzaza.com/houston-museum-district","location":"5701 Main Street, Houston, TX 77005, United States","lat":29.724255,"lng":-95.390087,"arrival":"Weekend weddings, museum events and themed-suite demand can slow valet; reserve spa and specialty rooms well ahead.","best":"Best for museum access, expressive design and a short ride to Montrose rather than doorstep bar-hopping.","crowd":"LGBTQ+ weekenders, couples, museum visitors, celebrations and business travellers create a broad upscale audience.","dress":"Creative city style feels natural; the restaurant and event rooms lean smart-casual while the pool remains resort casual.","inclusion":"Houston's dedicated LGBTQ tourism site recommends ZaZa in both hotel and Montrose planning content.","basis":"Multiple official Houston LGBTQ destination references plus the current property site.","class":"Luxury lifestyle hotel","coords":"Mapbox exact-address result for 5701 Main Street; relevance 1.0.","sources":["https://lgbtq.visithoustontexas.com/plan-your-vacation/hotels/haute-hotels-hit-city/","https://www.hotelzaza.com/houston-museum-district"]},
 {"name":"C. Baldwin, Curio Collection by Hilton","aliases":"C. Baldwin, Curio Collection by Hilton|C. Baldwin Hotel|C Baldwin Hotel","city":"houston","description":"A downtown Curio Collection hotel that hosted a public Pride drag brunch in June 2026. It offers a central full-service base for the parade, theatre district and city events rather than direct Montrose nightlife access.","vibe":"confident downtown hotel with contemporary Texas design and Pride events","tags":"luxury,social,mixed","hours":"Reception operates 24 hours; Rosalie, lobby bar, fitness and event spaces have independent schedules.","link":"https://www.hilton.com/en/hotels/houcuqq-c-baldwin/","location":"400 Dallas Street, Houston, TX 77002, United States","lat":29.757940,"lng":-95.371175,"arrival":"Corporate groups and weekend events can produce valet and check-in waves; brunch or event admission is separate from a room booking.","best":"Best for downtown Pride and cultural events, especially travellers prioritising central transit over walking home from Montrose bars.","crowd":"Queer Pride guests, business travellers, couples, event groups and local diners mix in a large mainstream hotel.","dress":"Everyday city clothing works for rooms; Rosalie and programmed brunches suit smart-casual or expressive Pride looks.","inclusion":"Visit Houston confirms the hotel's 2026 Pride drag brunch; this is documented programming, not a claim that every stay is queer-centred.","basis":"Current official destination Pride listing plus Hilton's official property record.","class":"Upscale downtown Curio Collection hotel","coords":"Mapbox exact-address result for 400 Dallas Street; relevance 1.0.","sources":["https://www.visithoustontexas.com/lgbtq/post/pride-month-in-houston/","https://www.hilton.com/en/hotels/houcuqq-c-baldwin/"]},

 {"name":"Dossier","aliases":"Dossier|Dossier Hotel","city":"portland","description":"A downtown boutique hotel named by Pride Northwest as an official Portland Pride 2026 hotel sponsor. Its central position supports waterfront Pride access while the hotel itself remains a mixed urban stay.","vibe":"tailored downtown boutique style with direct Pride-partner credibility","tags":"luxury,cultural,mixed","hours":"Reception operates 24 hours; restaurant, fitness and guest programming follow current schedules.","link":"https://www.dossierhotel.com/","location":"750 SW Alder Street, Portland, OR 97205, United States","lat":45.520080,"lng":-122.680146,"arrival":"Pride weekend and downtown events tighten rooms and valet capacity; use the organiser's current partner link when available.","best":"Best for a walkable downtown base between the Pearl, West End and Pride's waterfront activity.","crowd":"LGBTQIA2S+ Pride visitors, couples, business guests and design travellers mix in a refined boutique hotel.","dress":"Portland's relaxed city style works throughout; public dining spaces can feel polished without a formal code.","inclusion":"Pride Northwest publicly lists Dossier among its 2026 hotel sponsors, establishing direct support for the local LGBTQIA2S+ organisation.","basis":"Official Portland Pride 2026 hotel sponsorship plus first-party hotel details.","class":"Upscale boutique hotel","coords":"Mapbox exact-address result for 750 SW Alder Street; relevance 1.0.","sources":["https://portlandpride.org/travel-2026","https://www.dossierhotel.com/"]},
 {"name":"The Heathman Hotel","aliases":"The Heathman Hotel|Heathman Hotel","city":"portland","description":"A historic arts-focused hotel beside Portland's cultural district and an official Portland Pride 2026 hotel sponsor. It suits travellers who want civic culture and easy waterfront access more than an on-site party scene.","vibe":"literary Portland landmark combining cultural calm with Pride access","tags":"luxury,cultural,cozy","hours":"Reception operates 24 hours; library, dining and fitness access follow current hotel schedules.","link":"https://heathmanhotel.com/","location":"1001 SW Broadway, Portland, OR 97205, United States","lat":45.517161,"lng":-122.681088,"arrival":"Theatre nights and Pride weekend can crowd curb access; confirm parking and any sponsor rate before arrival.","best":"Best for performances, museums and a composed downtown stay within walking distance of Pride routes.","crowd":"Queer couples, arts travellers, theatre audiences and business guests create a quiet, mixed upscale crowd.","dress":"Casual layers are normal; smart-casual suits cultural evenings and dining without creating a restrictive door policy.","inclusion":"Pride Northwest lists The Heathman as a 2026 hotel sponsor and publishes a Pride booking offer.","basis":"Official Pride Northwest hotel partnership plus current hotel operation.","class":"Historic luxury hotel","coords":"Mapbox exact-address result for 1001 SW Broadway; relevance 1.0.","sources":["https://portlandpride.org/travel-2026","https://heathmanhotel.com/"]},
 {"name":"The Hotel Zags Portland","aliases":"The Hotel Zags Portland|Hotel Zags|The Hotel Zags","city":"portland","description":"A colourful downtown hotel with a gear-shed concept, courtyard and bike-friendly positioning. Pride Northwest lists it as a 2026 hotel sponsor with a special Pride offer.","vibe":"playful active Portland base with courtyard social space and Pride support","tags":"social,cultural,mixed","hours":"Reception operates 24 hours; restaurant, courtyard and equipment borrowing use current schedules.","link":"https://www.thehotelzags.com/","location":"515 SW Clay Street, Portland, OR 97201, United States","lat":45.513829,"lng":-122.680776,"arrival":"Borrowing equipment and event weekends add desk demand; secure Pride dates and accessible room requirements early.","best":"Best for active travellers who want downtown, waterfront and South Park Blocks access with a less formal mood.","crowd":"LGBTQIA2S+ Pride guests, cyclists, couples, families and weekend groups share an upbeat mixed hotel.","dress":"Practical layers and casual Portland clothing fit; courtyard events may publish their own theme.","inclusion":"Its named status in Pride Northwest's 2026 hotel programme provides a direct local-community relationship.","basis":"Official Portland Pride 2026 sponsorship and offer plus first-party hotel information.","class":"Lifestyle boutique hotel","coords":"Mapbox exact-address result for 515 SW Clay Street; relevance 1.0.","sources":["https://portlandpride.org/travel-2026","https://www.thehotelzags.com/"]},
 {"name":"The Hoxton Portland","aliases":"The Hoxton Portland|The Hoxton, Portland|The Hoxton","city":"portland","description":"A Chinatown hotel in a restored historic building, with compact rooms, public restaurants and basement nightlife. It is one of Pride Northwest's official 2026 hotel sponsors.","vibe":"social Chinatown design hotel with restaurants, basement energy and Pride ties","tags":"social,cultural,mixed","hours":"Reception operates 24 hours; restaurants, bar and basement events maintain separate schedules.","link":"https://thehoxton.com/portland/","location":"15 NW 4th Avenue, Portland, OR 97209, United States","lat":45.523358,"lng":-122.674735,"arrival":"Busy restaurant and nightlife periods can make the ground floor feel crowded; room check-in remains distinct from public events.","best":"Best for guests wanting an animated lobby, Old Town access and an easy link to waterfront Pride.","crowd":"Queer Pride travellers, creatives, food and design visitors, locals and weekend groups mix in highly public common spaces.","dress":"Individual style is common and casual; ticketed basement programmes may state age, bag or entry rules.","inclusion":"Pride Northwest's current sponsor list documents financial or in-kind support for Portland Pride 2026.","basis":"Official Pride Northwest hotel sponsorship plus official Hoxton property information.","class":"Lifestyle design hotel","coords":"Mapbox exact-address result for 15 NW 4th Avenue; relevance 1.0.","sources":["https://portlandpride.org/travel-2026","https://thehoxton.com/portland/"]},

 {"name":"Rehoboth Guest House","aliases":"Rehoboth Guest House|Rehoboth Guest House Bed & Breakfast|Rehoboth Guest House - Adults Only","city":"rehoboth_beach","description":"Delaware's surviving gay-owned and operated guest house, adults-only and active for more than forty years. It sits behind CAMP Rehoboth, close to Baltimore Avenue venues and a short walk from the ocean.","vibe":"historic gay-owned guest house with communal breakfast and social porches","tags":"cultural,cozy,social","hours":"Guest accommodation operates year-round with property-specific check-in; direct booking and quiet-house policies apply.","link":"https://www.rehobothguesthouse.com/","location":"40 Maryland Avenue, Rehoboth Beach, DE 19971, United States","lat":38.717715,"lng":-75.080296,"arrival":"Only fourteen rooms mean summer and event dates sell early; it is adults-only and not wheelchair accessible, so confirm fit before payment.","best":"Best for travellers who explicitly want queer ownership, conversation over breakfast and walking access to Baltimore Avenue.","crowd":"Gay men are historically central, while the current house welcomes adults across the LGBTQ+ community and respectful straight guests.","dress":"Beach-town casual throughout; shared spaces reward basic house etiquette and privacy rather than any appearance standard.","inclusion":"The property calls itself gay-owned and operated, and Delaware's official history programme documents its continuous queer role.","basis":"First-party ownership statement plus Delaware government LGBTQ history research.","class":"Adults-only gay-owned bed and breakfast","coords":"Mapbox exact-address result for 40 Maryland Avenue; relevance 1.0.","sources":["https://www.rehobothguesthouse.com/general-info/","https://history.delaware.gov/lgbtq/rehoboth-guest-house/"]},
 {"name":"Cambria Hotel Rehoboth Beach","aliases":"Cambria Hotel Rehoboth Beach|Cambria Hotel Rehoboth Beach - Rehoboth","city":"rehoboth_beach","description":"A modern full-service hotel west of downtown with indoor and outdoor pools, cabanas, restaurant and substantial event space. Visit Rehoboth places it in its dedicated LGBTQ+ Friendly Lodging category.","vibe":"amenity-rich inclusive resort base outside the walkable beach centre","tags":"relax,social,mixed","hours":"Reception operates 24 hours; pools, restaurant, fitness and seasonal cabana service use current schedules.","link":"https://www.choicehotels.com/delaware/rehoboth-beach/cambria-hotels/de019","location":"17222 Hood Road, Rehoboth Beach, DE 19971, United States","lat":38.726910,"lng":-75.136518,"arrival":"Parking is easier than downtown, but summer traffic on Route 1 matters; nightlife and Poodle Beach require a planned ride.","best":"Best for travellers prioritising pools, larger rooms and on-site facilities over walking directly to the boardwalk.","crowd":"Queer couples and groups mix with families, event guests and outlet-shopping visitors in a broad full-service hotel.","dress":"Resort casual works; swimwear stays in pool zones and restaurant or event rooms may use smart-casual guidance.","inclusion":"The local destination organisation explicitly categorises Cambria as LGBTQ+ Friendly Lodging.","basis":"Visit Rehoboth LGBTQ+ Friendly Lodging listing plus official Choice property record.","class":"Modern full-service hotel","coords":"Mapbox exact-address result for 17222 Hood Road; relevance 1.0.","sources":["https://www.visitrehoboth.com/category/lgbtq-friendly-lodging","https://www.choicehotels.com/delaware/rehoboth-beach/cambria-hotels/de019"]},
 {"name":"Homestead Bed & Breakfast","aliases":"Homestead Bed & Breakfast|The Homestead B&B|Homestead B&B","city":"rehoboth_beach","description":"A small country-chic bed and breakfast with six rooms, detached cottage, pool and dog-friendly grounds outside central Rehoboth. Visit Rehoboth lists it under LGBTQ+ Friendly Lodging.","vibe":"quiet inclusive country B&B with pool, garden and pet-friendly space","tags":"cozy,relax,mixed","hours":"Accommodation is reservation-led; breakfast, pool and check-in windows follow current house policies.","link":"https://homesteadrehoboth.com/","location":"35060 Warrington Road, Rehoboth Beach, DE 19971, United States","lat":38.718920,"lng":-75.132660,"arrival":"The small inventory fills quickly and a car or ride is needed for downtown; confirm pet, cottage and accessibility requirements directly.","best":"Best for queer couples wanting calm, breakfast and outdoor space away from the boardwalk's busiest blocks.","crowd":"LGBTQ+ guests, couples, pet travellers and repeat beach visitors share an intimate mixed B&B environment.","dress":"Informal beach and garden clothing fits; pool, breakfast and shared grounds depend on considerate house etiquette.","inclusion":"Visit Rehoboth includes the property in its explicit LGBTQ+ Friendly Lodging category.","basis":"Local destination LGBTQ+ lodging classification plus the property's current accommodation information.","class":"Small pet-friendly bed and breakfast","coords":"Mapbox exact-address result for 35060 Warrington Road; relevance 1.0.","sources":["https://www.visitrehoboth.com/category/lgbtq-friendly-lodging","https://homesteadrehoboth.com/"]},
 {"name":"Hotel Rehoboth","aliases":"Hotel Rehoboth","city":"rehoboth_beach","description":"A central boutique hotel on Rehoboth Avenue with breakfast, evening wine service, seasonal beach shuttle and on-site restaurant. It is not queer-exclusive; its value for queer travellers is walkability to the town's established LGBTQ+ social core.","vibe":"central boutique comfort linking beach service with queer-district walkability","tags":"luxury,relax,mixed","hours":"Reception and lodging operate daily; breakfast, shuttle, restaurant and seasonal services have separate hours.","link":"https://www.hotelrehoboth.com/","location":"247 Rehoboth Avenue, Rehoboth Beach, DE 19971, United States","lat":38.716063,"lng":-75.084962,"arrival":"On-site parking reduces downtown friction; peak summer dates still require early booking and shuttle timing should be confirmed.","best":"Best for guests wanting full hotel service and a walkable route to Baltimore Avenue without choosing an adults-only guest house.","crowd":"Queer couples, beach visitors, families and restaurant guests form a mainstream mixed hotel crowd in an LGBTQ-visible town.","dress":"Beach casual works across the property; Lupo and evening wine service suit neat resort-casual clothing.","inclusion":"Queer relevance is based on its central position inside Rehoboth's documented LGBTQ destination, not an unsupported ownership or certification claim.","basis":"Official hotel information paired with Delaware's official LGBTQ travel guide; inclusion scope stated conservatively.","class":"Independent luxury boutique hotel","coords":"Mapbox exact-address result for 247 Rehoboth Avenue; relevance 1.0.","sources":["https://www.hotelrehoboth.com/rehoboth-beach-accommodations","https://www.visitdelaware.com/blog/post/lgbtqia-travel-guide-to-rehoboth-beach-delaware/"]},

 {"name":"RISE Uptown Hotel","aliases":"RISE Uptown Hotel|Rise Uptown|ARRIVE Phoenix","city":"phoenix","description":"A restored mid-century hotel immediately north of the Melrose District, with swim-up pool bar, rooftop cocktails and neighbourhood food concepts. Visit Phoenix names it as the stay option in its official guide to the city's gayborhood.","vibe":"mid-century pool hotel beside Melrose with strong local social energy","tags":"social,cultural,relax","hours":"Guest service operates daily; Lylo, Say When, pool and food outlets maintain separate schedules and age policies.","link":"https://riseuptownhotel.com/","location":"400 W Camelback Road, Phoenix, AZ 85013, United States","lat":33.509769,"lng":-112.079580,"arrival":"Pool and rooftop popularity can crowd parking and public spaces; confirm guest-only access and extreme-heat procedures in summer.","best":"Best for immediate access to Melrose bars and a social pool stay rather than downtown convention travel.","crowd":"Queer weekenders, local pool guests, couples, design travellers and neighbourhood regulars create an adult-leaning mixed scene.","dress":"Desert resort casual works by day; rooftop evenings become polished but no queer-specific appearance rule is published.","inclusion":"Visit Phoenix explicitly recommends RISE in the Where to Stay section of its Melrose LGBTQ+ district guide.","basis":"Official destination LGBTQ neighbourhood recommendation plus current first-party hotel details.","class":"Independent mid-century lifestyle hotel","coords":"Mapbox exact-address result for 400 W Camelback Road; relevance 1.0.","sources":["https://www.visitphoenix.com/lgbtq/melrose-district/","https://riseuptownhotel.com/"]},
 {"name":"Royal Palms Resort and Spa","aliases":"Royal Palms Resort and Spa|Royal Palms Resort & Spa","city":"phoenix","description":"A historic luxury resort at Camelback Mountain with casita-style rooms, gardens, spa and restaurant. Visit Phoenix publishes a 2026 Pride stay offer stating that LGBTQ+ guests are welcomed during Pride and beyond.","vibe":"romantic desert resort with gardens, spa calm and explicit Pride welcome","tags":"luxury,relax,cozy","hours":"Reception operates 24 hours; spa, pool, restaurant and experiences require current schedules or reservations.","link":"https://www.hyatt.com/unbound-collection/en-US/phxub-royal-palms-resort-and-spa","location":"5200 E Camelback Road, Phoenix, AZ 85018, United States","lat":33.503962,"lng":-111.968080,"arrival":"Valet is standard and resort experiences should be booked separately; summer heat changes how guests move through outdoor paths.","best":"Best for couples seeking a quiet celebratory resort stay rather than walking access to Melrose nightlife.","crowd":"LGBTQ+ couples, spa travellers, weddings and luxury leisure guests share a calm mainstream resort.","dress":"Resort casual by day and smart-casual for dinner; pool and spa maintain activity-specific rules.","inclusion":"The current Visit Phoenix Pride package explicitly says the resort welcomes guests during Pride month and beyond.","basis":"Current 2026 official destination Pride offer plus Hyatt's property information.","class":"Historic luxury desert resort","coords":"Mapbox exact-address result for 5200 E Camelback Road; relevance 1.0.","sources":["https://www.visitphoenix.com/coupon/stay-and-celebrate-pride-20%25-off/5648/print/","https://www.hyatt.com/unbound-collection/en-US/phxub-royal-palms-resort-and-spa"]},
 {"name":"Kimpton Hotel Palomar Phoenix","aliases":"Kimpton Hotel Palomar Phoenix|Hotel Palomar Phoenix|Palomar Phoenix CityScape","city":"phoenix","description":"A renovated downtown boutique hotel at CityScape with rooftop pool, social hour and restaurant. Its current specialist LGBTQ+ approval and Kimpton's established inclusion programme provide the queer-friendly signal.","vibe":"bright downtown Kimpton with rooftop social life and Pride-ready service","tags":"luxury,social,mixed","hours":"Reception operates 24 hours; rooftop pool, Eden Bar, restaurant and social hour follow current schedules.","link":"https://www.hotelpalomar-phoenix.com/","location":"2 E Jefferson Street, Phoenix, AZ 85004, United States","lat":33.447532,"lng":-112.073349,"arrival":"Arena and convention dates can pressure valet, lifts and rooftop seating; reserve cabanas or dining apart from the room.","best":"Best for downtown events, light rail and guests wanting a visibly queer-friendly brand with city-centre convenience.","crowd":"LGBTQ+ couples and groups mix with sports fans, business travellers and rooftop visitors in an active mainstream hotel.","dress":"Expressive city and pool styles fit; the rooftop and restaurant lean smart-casual without a published restrictive code.","inclusion":"Travel Gay currently marks the property approved and a Phoenix Pride partner; Kimpton also maintains a brand-level LGBTQ+ programme.","basis":"Current specialist LGBTQ+ approval plus official hotel and Kimpton records.","class":"Upscale Kimpton lifestyle hotel","coords":"Mapbox exact-address result for 2 E Jefferson Street; relevance 1.0.","sources":["https://www.travelgay.com/gay-phoenix-hotels","https://www.hotelpalomar-phoenix.com/"]},
 {"name":"Renaissance Phoenix Downtown Hotel","aliases":"Renaissance Phoenix Downtown Hotel|Renaissance Phoenix Downtown","city":"phoenix","description":"A large art-led downtown hotel beside the convention centre, arena and light rail. Phoenix Pride has documented it as a community-level sponsor, while the current Marriott record confirms active hotel operation and access details.","vibe":"large downtown arts hotel with documented Phoenix Pride support","tags":"luxury,cultural,mixed","hours":"Reception operates 24 hours; rooftop, pool, restaurants and club lounge follow current renovation and operating notices.","link":"https://www.marriott.com/en-us/hotels/phxbd-renaissance-phoenix-downtown-hotel/overview/","location":"100 N 1st Street, Phoenix, AZ 85004, United States","lat":33.449579,"lng":-112.072857,"arrival":"Convention waves can create busy check-in and valet periods; verify the current rooftop renovation before booking for pool use.","best":"Best for Pride-related downtown events, conventions and transit, not for walking directly to Melrose nightlife.","crowd":"LGBTQ+ event visitors, convention groups, sports audiences and business travellers share a large mixed property.","dress":"No hotel-wide code; smart-casual fits the lobby and dining outlets, while event programming may set its own terms.","inclusion":"Phoenix Pride's published annual report records the hotel as a sponsor; this is historical institutional evidence, not a claim of queer exclusivity.","basis":"Phoenix Pride sponsor documentation plus the current official Marriott property page.","class":"Large upscale downtown hotel","coords":"Mapbox exact-address result for 100 N 1st Street; relevance 1.0.","sources":["https://phoenixpride.org/wp-content/uploads/2021/07/2020-Annual-report-updated-2.17.2021.pdf","https://www.marriott.com/en-us/hotels/phxbd-renaissance-phoenix-downtown-hotel/overview/"]},

 {"name":"Queen Kapiolani Hotel Waikiki Beach","aliases":"Queen Kapiolani Hotel Waikiki Beach|Queen Kapi'olani Hotel|Queen Kapiʻolani Hotel","city":"honolulu","description":"A colourful hotel by Kapiolani Park and Queen's Surf, with Diamond Head views and a documented Honolulu Pride partnership. Its own site lists 2026 Pride VIP access and accessible-room detail.","vibe":"bright Diamond Head hotel beside queer beach life and Honolulu Pride","tags":"social,cultural,mixed","hours":"Reception operates daily; pool, DECK restaurant, surf school and Pride events use separate schedules.","link":"https://www.queenkapiolani.com/","location":"150 Kapahulu Avenue, Honolulu, HI 96815, United States","lat":21.271973,"lng":-157.821180,"arrival":"Pride and Waikiki event dates can crowd valet and lifts; request specific accessible features rather than assuming every room is identical.","best":"Best for walking to Queen's Surf, Hula's and the Pride route while retaining full hotel facilities.","crowd":"LGBTQIA+ Pride visitors, beach travellers, families, surfers and local restaurant guests mix in an open resort environment.","dress":"Resort casual works; dry cover-ups are appropriate away from the beach and Pride events can invite expressive looks.","inclusion":"The hotel has published its Honolulu Pride partnership and currently lists 2026 Pride VIP programming.","basis":"First-party Pride partnership and event record plus current official hotel information.","class":"Full-service Waikiki lifestyle hotel","coords":"Mapbox exact-address result for 150 Kapahulu Avenue; relevance 1.0.","sources":["https://www.queenkapiolani.com/newsroom","https://www.queenkapiolani.com/events/honolulu/honolulu-pride-vip-passes-12388553"]},
 {"name":"Alohilani Resort Waikiki Beach","aliases":"Alohilani Resort Waikiki Beach|ʻAlohilani Resort Waikiki Beach|'Alohilani Resort Waikiki Beach","city":"honolulu","description":"A large Waikiki resort with oceanarium, rooftop pool and restaurants that runs a current Pride Amplified stay offer and dedicated Pride pool programming. Its inclusion message explicitly extends beyond one celebration.","vibe":"high-energy Waikiki resort pairing rooftop polish with active Pride programming","tags":"luxury,social,relax","hours":"Reception operates 24 hours; pool, oceanarium, restaurants, club and event access use separate schedules.","link":"https://www.alohilaniresort.com/","location":"2490 Kalakaua Avenue, Honolulu, HI 96815, United States","lat":21.274419,"lng":-157.823661,"arrival":"A large resort creates transfer and lift peaks; Pride pool events may need separate tickets even for overnight guests.","best":"Best for travellers wanting full resort infrastructure, central Waikiki and visible queer programming on selected dates.","crowd":"LGBTQ+ Pride guests, couples, families, international groups and pool-event visitors create a broad, busy resort audience.","dress":"Resort wear by day; restaurants, club areas and programmed pool events establish their own smart-casual or swim rules.","inclusion":"The first-party Pride Amplified offer describes belonging beyond a single moment, reinforced by the resort's own 2026 Pride event calendar.","basis":"Current first-party LGBTQ+ stay package and Pride programming.","class":"Large luxury Waikiki resort","coords":"Mapbox exact-address result for 2490 Kalakaua Avenue; relevance 1.0.","sources":["https://www.alohilaniresort.com/special-offers/pride-amplified/","https://www.alohilaniresort.com/waikiki-events/month/2026-06/"]},
 {"name":"White Sands Hotel","aliases":"White Sands Hotel|White Sands Hotel Waikiki","city":"honolulu","description":"A low-rise 1957 Waikiki hotel with private lanais, tropical courtyard, pool and cocktail bars. Honolulu Pride lists White Sands among its 2026 supporters, while the hotel supplies current property and accessibility details.","vibe":"retro tropical hideaway with poolside personality and local Pride support","tags":"cultural,social,cozy","hours":"Reception operates daily; Heyday, Green Lady, pool, yoga and live music follow their own schedules.","link":"https://www.whitesandshotel.com/","location":"431 Nohonani Street, Honolulu, HI 96815, United States","lat":21.280045,"lng":-157.825452,"arrival":"Exterior walk-up corridors and no tower-style layout require an access check; central parking and Pride dates can be constrained.","best":"Best for queer travellers wanting a smaller retro property near Waikiki nightlife rather than a high-rise resort.","crowd":"LGBTQIA+ Pride visitors, design travellers, couples, bar guests and leisure groups mix around a compact courtyard.","dress":"Colourful resort casual fits; swimwear belongs at the pool and the hidden cocktail room is comfortable in neat evening clothes.","inclusion":"White Sands appears among Honolulu Pride's current supporters; the claim is partnership-based rather than queer ownership.","basis":"Official Honolulu Pride 2026 supporter listing plus first-party hotel fact sheet.","class":"Independent retro boutique hotel","coords":"Mapbox exact-address result for 431 Nohonani Street; relevance 1.0.","sources":["https://www.honolulupride.com/","https://www.whitesandshotel.com/fact-sheet/"]},
 {"name":"Romer House Waikiki","aliases":"Romer House Waikiki|Romer House Waikīkī|Romer House Waikiki - Adults Only","city":"honolulu","description":"An adults-only Waikiki neighbourhood hotel whose own local guide explicitly maps Hula's and Wang Chung's as queer nightlife. Pool events and small-scale design give it a sociable alternative to the large resorts.","vibe":"adults-only neighbourhood hotel tuned into Waikiki's queer night rhythm","tags":"social,cultural,cozy","hours":"Reception operates daily; pool deck, bar and programmed happenings use separate hours and ticket rules.","link":"https://www.romerhotels.com/romer-house-waikiki","location":"415 Nahua Street, Honolulu, HI 96815, United States","lat":21.279320,"lng":-157.825132,"arrival":"Adults-only operation should be confirmed at booking; pool parties can bring separate ticket and parking demand.","best":"Best for adults wanting a smaller social base whose editorial guide understands nearby queer venues.","crowd":"Queer couples and friends, design travellers, local event guests and other adults share a mixed, social hotel.","dress":"Island casual fits most spaces; pool programmes invite expressive swim looks while respecting consent and photography boundaries.","inclusion":"The hotel's own neighbourhood guide describes Hula's queer roots and Wang Chung's queer crowd directly rather than erasing local LGBTQ+ context.","basis":"First-party queer-aware destination guidance plus current property and event operation.","class":"Adults-only lifestyle hotel","coords":"Mapbox exact-address result for 415 Nahua Street; relevance 1.0.","sources":["https://www.romerhotels.com/romer-house-waikiki/neighborhood/nighttime-in-waikiki","https://www.romerhotels.com/romer-house-waikiki"]},
 {"name":"Kaimana Beach Hotel","aliases":"Kaimana Beach Hotel|New Otani Kaimana Beach Hotel","city":"honolulu","description":"A beachfront boutique hotel on Waikiki's quieter Gold Coast, beside a long-popular queer beach corridor. Its current site promotes a Pride stay and the Hawaiʻi LGBT Legacy Foundation documents an ongoing diversity-and-inclusion partnership.","vibe":"calm beachfront boutique stay with explicit Pride welcome and local character","tags":"relax,cozy,cultural","hours":"Reception operates daily; Hau Tree dining, beach equipment and guest experiences follow current schedules.","link":"https://www.kaimana.com/","location":"2863 Kalakaua Avenue, Honolulu, HI 96815, United States","lat":21.263433,"lng":-157.821189,"arrival":"Valet and restaurant demand can peak at brunch and sunset; the location is quieter but farther from central Waikiki nightlife.","best":"Best for couples prioritising sand, Diamond Head and a verified queer-welcoming stay over late-night density.","crowd":"LGBTQ+ couples, surfers, local diners, design travellers and relaxed international guests share a mixed beachfront property.","dress":"Beach and resort casual dominate; use cover-ups in dining spaces and choose practical footwear for the shoreline.","inclusion":"Kaimana currently advertises its Pride the Wave stay, while the local LGBT foundation records that it celebrates diversity and inclusion every day.","basis":"Current first-party Pride offer plus documented Hawaiʻi LGBT Legacy Foundation partnership.","class":"Oceanfront boutique hotel","coords":"Mapbox exact-address result for 2863 Kalakaua Avenue; relevance 1.0.","sources":["https://www.kaimana.com/","https://hawaiilgbtlegacyfoundation.com/2023-travel-partners/"]}
]
$qa_hotels$) h(name text,aliases text,city text,description text,vibe text,tags text,hours text,link text,location text,lat double precision,lng double precision,arrival text,best text,crowd text,dress text,inclusion text,basis text,class text,coords text,sources jsonb)
), hotels as (
  select h.*,
  array(
    select distinct case tag
      when 'playful' then 'social'
      when 'queer-owned' then 'cultural'
      when 'romantic' then 'cozy'
      else tag
    end
    from unnest(string_to_array(h.tags,',')) tag
  ) as normalized_tags,
  jsonb_build_object(
    'queue_wait',arrival,'best_nights',best,'crowd_mix',crowd,'dress_code',dress,
    'staff_inclusivity',inclusion,'inclusion_basis',basis,'hotel_class',class,
    'coordinate_source',coords,'source_urls',sources,
    'research_status','official_or_documented_lgbtq_sources_exact_address',
    'updated_at','2026-08-27T00:00:00Z'
  ) intel from raw_hotels h
), updated as (
  update public.places p set
    name=h.name,type='hotel',description=h.description,vibe=h.vibe,
    vibe_tags=h.normalized_tags,hours=h.hours,link=h.link,
    location=h.location,lat=h.lat,lng=h.lng,
    venue_intel=coalesce(p.venue_intel,'{}'::jsonb)||h.intel,
    seo_indexable=true,seo_quality_status='approved',updated_at=timezone('utc',now())
  from hotels h
  where lower(trim(p.city))=h.city and lower(trim(p.name)) in (
    select lower(trim(alias_name)) from unnest(string_to_array(h.aliases,'|')) alias_name
  ) returning p.id
)
insert into public.places(name,city,type,description,vibe,vibe_tags,hours,link,location,lat,lng,venue_intel,seo_indexable,seo_quality_status,updated_at)
select h.name,h.city,'hotel',h.description,h.vibe,h.normalized_tags,h.hours,h.link,h.location,h.lat,h.lng,h.intel,true,'approved',timezone('utc',now())
from hotels h where not exists (
  select 1 from public.places p where lower(trim(p.city))=h.city and lower(trim(p.name)) in (
    select lower(trim(alias_name)) from unnest(string_to_array(h.aliases,'|')) alias_name
  )
);

commit;

-- Result must be at least 4 hotels per city and 6 in Honolulu.
select city,count(*) filter(where type='hotel') as hotel_count,
  case when city='honolulu' then count(*) filter(where type='hotel')>=6
       else count(*) filter(where type='hotel')>=4 end as target_met
from public.places
where lower(trim(city)) in ('houston','portland','rehoboth_beach','phoenix','honolulu')
group by city order by city;

-- New/updated batch rows must all contain complete intelligence and coordinates.
select city,count(*) as batch_rows,
  count(*) filter(where
    coalesce(venue_intel->>'queue_wait','')<>'' and coalesce(venue_intel->>'best_nights','')<>'' and
    coalesce(venue_intel->>'crowd_mix','')<>'' and coalesce(venue_intel->>'dress_code','')<>'' and
    coalesce(venue_intel->>'staff_inclusivity','')<>'' and
    jsonb_array_length(coalesce(venue_intel->'source_urls','[]'::jsonb))>=2 and
    lat between -90 and 90 and lng between -180 and 180 and coalesce(location,'')<>''
  ) as complete_rows
from public.places
where type='hotel' and venue_intel->>'updated_at'='2026-08-27T00:00:00Z'
  and lower(trim(city)) in ('houston','portland','rehoboth_beach','phoenix','honolulu')
group by city order by city;

